const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args && typeof source.args === 'object' ? source.args : source;
const tool = String(source.tool || '').trim();
const apiKey = String($env.GOOGLE_MAPS_API_KEY || '').trim();
const defaultLanguage = String($env.MIA_MAPS_DEFAULT_LANGUAGE || 'vi').trim() || 'vi';
const defaultRegion = String($env.MIA_MAPS_DEFAULT_REGION || 'VN').trim() || 'VN';
const maxPlaceResults = Math.max(1, Math.min(Number($env.MIA_MAPS_MAX_PLACE_RESULTS || 5), 10));
if (tool !== 'maps.help' && !apiKey) {
  return [{ json: { ok: false, tool, error: 'Missing GOOGLE_MAPS_API_KEY.' } }];
}
const clean = (value) => String(value || '').trim();
const language = clean(args.language) || defaultLanguage;
const region = clean(args.region) || defaultRegion;
let method = 'GET';
let url = '';
let body = {};
let headers = {};
let fieldMask = '';
let helpMode = false;
if (tool === 'maps.help') {
  helpMode = true;
} else if (tool === 'maps.geocode') {
  const address = clean(args.address);
  if (!address) return [{ json: { ok: false, tool, error: 'Address is required for geocoding.' } }];
  url = `https://maps.googleapis.com/maps/api/geocode/json?address=${encodeURIComponent(address)}&language=${encodeURIComponent(language)}&region=${encodeURIComponent(region)}&key=${encodeURIComponent(apiKey)}`;
} else if (tool === 'maps.reverse_geocode') {
  const latLng = clean(args.latLng) || `${clean(args.latitude)},${clean(args.longitude)}`.replace(/^,|,$/g, '');
  if (!latLng || !/^-?\d+(?:\.\d+)?\s*,\s*-?\d+(?:\.\d+)?$/.test(latLng)) return [{ json: { ok: false, tool, error: 'latLng must be in "lat,lng" format.' } }];
  url = `https://maps.googleapis.com/maps/api/geocode/json?latlng=${encodeURIComponent(latLng)}&language=${encodeURIComponent(language)}&key=${encodeURIComponent(apiKey)}`;
} else if (tool === 'maps.search_place') {
  const query = clean(args.query);
  if (!query) return [{ json: { ok: false, tool, error: 'Query is required for place search.' } }];
  method = 'POST';
  url = 'https://places.googleapis.com/v1/places:searchText';
  headers = { 'X-Goog-Api-Key': apiKey };
  fieldMask = 'places.id,places.displayName,places.formattedAddress,places.location,places.googleMapsUri,places.primaryType,places.rating,places.userRatingCount';
  body = {
    textQuery: query,
    languageCode: language,
    regionCode: region,
    maxResultCount: Math.max(1, Math.min(Number(args.maxResults || maxPlaceResults), maxPlaceResults)),
  };
  if (clean(args.locationBias)) {
    const pair = clean(args.locationBias).split(',').map((item) => item.trim());
    if (pair.length === 2 && pair.every(Boolean)) {
      body.locationBias = {
        circle: {
          center: { latitude: Number(pair[0]), longitude: Number(pair[1]) },
          radius: 5000,
        },
      };
    }
  }
  if (args.openNow) body.openNow = true;
} else if (tool === 'maps.place_details') {
  const placeId = clean(args.placeId);
  if (!placeId) return [{ json: { ok: false, tool, error: 'placeId is required for place details.' } }];
  url = `https://places.googleapis.com/v1/places/${encodeURIComponent(placeId)}?languageCode=${encodeURIComponent(language)}`;
  headers = { 'X-Goog-Api-Key': apiKey };
  fieldMask = 'id,displayName,formattedAddress,location,googleMapsUri,primaryType,nationalPhoneNumber,websiteUri,rating,userRatingCount,regularOpeningHours';
} else if (tool === 'maps.compute_route') {
  const origin = clean(args.origin);
  const destination = clean(args.destination);
  if (!origin || !destination) return [{ json: { ok: false, tool, error: 'Origin and destination are required for route computation.' } }];
  method = 'POST';
  url = 'https://routes.googleapis.com/directions/v2:computeRoutes';
  headers = { 'X-Goog-Api-Key': apiKey };
  fieldMask = 'routes.duration,routes.distanceMeters,routes.localizedValues,routes.legs,routes.viewport';
  body = {
    origin: { address: origin },
    destination: { address: destination },
    travelMode: clean(args.travelMode).toUpperCase() || 'DRIVE',
    languageCode: language,
    units: 'METRIC',
  };
  if (clean(args.departureTime)) body.departureTime = clean(args.departureTime);
} else {
  return [{ json: { ok: false, tool, error: `Unsupported Maps tool: ${tool}` } }];
}
return [{ json: { ...source, ok: true, tool, helpMode, method, url, body, headers, fieldMask, language, region } }];

const source = $('Normalize Maps Request').item.json || {};
const freeEssentials = '10.000';
const freePro = '5.000';
const freeEnterprise = '1.000';
const lines = [
  'Google Maps hiện hỗ trợ các nhóm việc sau:',
  '1. Tìm tọa độ từ địa chỉ hoặc tên địa điểm.',
  '2. Tìm địa chỉ từ tọa độ.',
  '3. Tìm địa điểm theo từ khóa như quán ăn, cà phê, ATM, khách sạn.',
  '4. Xem chi tiết một địa điểm khi đã có placeId.',
  '5. Tính tuyến đường giữa hai điểm và ước lượng quãng đường / thời gian.',
  '',
  'Guardrail chi phí:',
  `- Luôn giới hạn kết quả tìm địa điểm ở mức thấp để tiết kiệm quota.`,
  `- Theo trang pricing của Google Maps Platform, free usage cap mỗi SKU / tháng hiện là khoảng ${freeEssentials} lượt cho Essentials, ${freePro} cho Pro và ${freeEnterprise} cho Enterprise; tài khoản mới còn có trial credit riêng.`,
  '- Nên bật budget alert trong Google Cloud để tránh vượt mức miễn phí.',
];
return [{ json: { ok: true, tool: source.tool || 'maps.help', text: lines.join('\n'), result: { pricingReference: 'https://developers.google.com/maps/billing-and-pricing/pricing' }, links: ['https://developers.google.com/maps/billing-and-pricing/overview', 'https://developers.google.com/maps/billing-and-pricing/pricing'], meta: { requestId: source.requestId || '' } } }];

const source = $('Normalize Maps Request').item.json || {};
const data = $json || {};
const tool = source.tool || '';
const failText = String(data.error_message || data.error?.message || data.message || '').trim();
if (failText && tool.startsWith('maps.')) {
  return [{ json: { ok: false, tool, text: failText, result: data, links: [], meta: { requestId: source.requestId || '' } } }];
}
function formatCoordinate(location) {
  if (!location) return '';
  if (location.latitude != null && location.longitude != null) return `${location.latitude}, ${location.longitude}`;
  if (location.lat != null && location.lng != null) return `${location.lat}, ${location.lng}`;
  return '';
}
let text = 'Không có dữ liệu bản đồ phù hợp.';
let links = [];
if (tool === 'maps.geocode' || tool === 'maps.reverse_geocode') {
  const rows = Array.isArray(data.results) ? data.results : [];
  if (rows.length) {
    text = rows.slice(0, 5).map((item, index) => {
      const coordinate = formatCoordinate(item.geometry?.location);
      return `${index + 1}. ${item.formatted_address || '(không rõ địa chỉ)'}${coordinate ? ` | ${coordinate}` : ''}`;
    }).join('\n');
  }
} else if (tool === 'maps.search_place') {
  const rows = Array.isArray(data.places) ? data.places : [];
  if (rows.length) {
    text = rows.map((item, index) => {
      const coordinate = formatCoordinate(item.location);
      const mapsLink = item.googleMapsUri || '';
      if (mapsLink) links.push(mapsLink);
      const rating = item.rating ? ` | rating ${item.rating}${item.userRatingCount ? ` (${item.userRatingCount})` : ''}` : '';
      return `${index + 1}. ${item.displayName?.text || item.formattedAddress || '(không rõ tên)'} | ${item.formattedAddress || 'không rõ địa chỉ'}${coordinate ? ` | ${coordinate}` : ''}${rating}`;
    }).join('\n');
  }
} else if (tool === 'maps.place_details') {
  const name = data.displayName?.text || '(không rõ tên)';
  const address = data.formattedAddress || 'không rõ địa chỉ';
  const coordinate = formatCoordinate(data.location);
  const phone = data.nationalPhoneNumber ? `\nSố điện thoại: ${data.nationalPhoneNumber}` : '';
  const website = data.websiteUri ? `\nWebsite: ${data.websiteUri}` : '';
  const rating = data.rating ? `\nĐánh giá: ${data.rating}${data.userRatingCount ? ` (${data.userRatingCount})` : ''}` : '';
  if (data.googleMapsUri) links.push(data.googleMapsUri);
  text = `${name}\nĐịa chỉ: ${address}${coordinate ? `\nTọa độ: ${coordinate}` : ''}${rating}${phone}${website}`;
} else if (tool === 'maps.compute_route') {
  const route = Array.isArray(data.routes) ? data.routes[0] : null;
  if (route) {
    const distance = route.localizedValues?.distance?.text || (route.distanceMeters ? `${Math.round(Number(route.distanceMeters) / 1000)} km` : 'không rõ');
    const duration = route.localizedValues?.duration?.text || route.duration || 'không rõ';
    const leg = Array.isArray(route.legs) ? route.legs[0] : null;
    const startAddress = leg?.startLocation?.address || source.args?.origin || '';
    const endAddress = leg?.endLocation?.address || source.args?.destination || '';
    text = `Tuyến đường ${startAddress || 'điểm đi'} -> ${endAddress || 'điểm đến'}\nQuãng đường: ${distance}\nThời gian ước tính: ${duration}`;
  }
}
return [{ json: { ok: true, tool, text, result: data, links: links.slice(0, 3), meta: { requestId: source.requestId || '' } } }];
